// Des: Cloud flow: upload with failover, purge layers, keepalive, verify
// Flo: pick first healthy store + database > sync (3 tries, the failing layer is skipped) > per store page purge > database ladder > local purge > weekly keepalive and verify > alerts as text lines
// I/O: Flow (vendor lists with caps, local Db, Conf, clock) > Fres counts and alert lines; dryz plans only, no write, no network write
// ===================================================================
const std = @import("std"); const sync = @import("sy-clou-sync.zig"); const stor = @import("sy-clou-stor.zig"); const sqlz = @import("sy-clou-sqlz.zig"); const sqli = @import("st-stor-sqli.zig"); const cfgz = @import("cf-conf-load.zig"); const fail = @import("ru-fail-over.zig"); const outb = @import("sy-clou-outb.zig"); const pclo = @import("ru-purg-clou.zig"); const snap = @import("sy-carz-snap.zig"); const cbak = @import("sy-cont-back.zig"); const pdbz = @import("ru-purg-dbzz.zig"); const ploc = @import("ru-purg-loca.zig"); const kplv = @import("ru-keep-live.zig"); const mkit = @import("ru-mirr-flow.zig"); const mirr = @import("sy-mirr-stor.zig"); const msql = @import("sy-mirr-sqlz.zig");
pub const Vend = struct { name: []const u8, store: stor.Stor, capb: u64 };
pub const Vsqd = struct { name: []const u8, sql2: sqlz.Sqlz, capb: u64 };
pub const Flow = struct { iozz: std.Io, dbzz: *sqli.Dbzz, dirz: []const u8, conf: cfgz.Conf, stos: []const Vend, sqls: []const Vsqd, dryz: bool = false, lcap: u64 = 0, ckey: ?[32]u8 = null };
pub const Fres = struct { sres: sync.Sres = .{}, stor: []const u8 = "", sqlv: []const u8 = "", tris: u8 = 0, pac4: u32 = 0, kept: u32 = 0, comp: u32 = 0, bads: u32 = 0, errs: u32 = 0, blan: u32 = 0, gone: u32 = 0, loca: ploc.Lres = .{}, live: kplv.Kres = .{}, veri: kplv.Kres = .{}, alrt: []const []const u8 = &.{}, mirr: mkit.Mres = .{} };
fn pickFirs(self: *Flow, aren: std.mem.Allocator, nowz: i64, isst: bool, skip: []const []const u8) !?usize { const cont = if (isst) self.stos.len else self.sqls.len; const nams = try aren.alloc([]const u8, cont); for (0..cont) |indx| nams[indx] = if (isst) self.stos[indx].name else self.sqls[indx].name; return fail.failFirs(self.dbzz, nams, skip, nowz); }
fn copyFirs(self: *Flow, nowz: i64, sidx: usize) !?stor.Stor { if (!self.conf.purg_copy_enab) return null; for (self.stos, 0..) |item, indx| { if (indx == sidx) continue; if (try fail.failOkay(self.dbzz, item.name, nowz)) return item.store; } return null; }
fn kitzMake(self: *Flow, aren: std.mem.Allocator, nowz: i64) !?*mkit.Kitz { if (!self.conf.clou_mirr_enab) return null; const smem = try aren.alloc(mirr.Memb, self.stos.len); for (self.stos, 0..) |item, indx| smem[indx] = .{ .name = item.name, .store = item.store, .idxz = indx }; const qmem = try aren.alloc(msql.Smem, self.sqls.len); for (self.sqls, 0..) |item, indx| qmem[indx] = .{ .name = item.name, .sql2 = item.sql2, .idxz = indx }; return try mkit.kitzOpen(aren, self.dbzz, nowz, smem, qmem); }
fn capzSqlz(self: *Flow, kitz: ?*mkit.Kitz, qidx: usize) u64 { var capz = self.sqls[qidx].capb; const ktzz = kitz orelse return capz; for (self.sqls, 0..) |item, indx| { if (indx == qidx or ktzz.qdea.dead[indx] or item.capb == 0) continue; if (capz == 0 or item.capb < capz) capz = item.capb; } return capz; }
fn makeSync(self: *Flow, aren: std.mem.Allocator, nowz: i64, sidx: usize, qidx: usize, kitz: ?*mkit.Kitz) !sync.Sync { const pool = try aren.alloc(sync.Vsto, self.stos.len); for (self.stos, 0..) |item, indx| pool[indx] = .{ .name = item.name, .store = item.store }; const sqls = try aren.alloc(sync.Vsql, self.sqls.len); for (self.sqls, 0..) |item, indx| sqls[indx] = .{ .name = item.name, .sql2 = item.sql2 }; return .{ .iozz = self.iozz, .dbzz = self.dbzz, .dirz = self.dirz, .conf = self.conf, .store = if (kitz) |ktzz| mirr.fanzStor(try mkit.fanzForz(ktzz, aren, self.dbzz, self.iozz, nowz, self.conf, sidx, true)) else self.stos[sidx].store, .sql2 = if (kitz) |ktzz| msql.sanzSqlz(try mkit.sanzForz(ktzz, aren, self.dbzz, self.iozz, nowz, self.conf, qidx)) else self.sqls[qidx].sql2, .copy = if (kitz != null) null else try copyFirs(self, nowz, sidx), .vnam = self.stos[sidx].name, .pool = pool, .sqls = sqls, .dryz = self.dryz }; }
fn alrtAddz(aren: std.mem.Allocator, list: *std.ArrayList([]const u8), comptime fmtz: []const u8, args: anytype) !void { try list.append(aren, try std.fmt.allocPrint(aren, fmtz, args)); }
fn phas(self: *Flow, aren: std.mem.Allocator, nowz: i64, synz: *sync.Sync, qidx: usize, kitz: ?*mkit.Kitz, fres: *Fres, alrt: *std.ArrayList([]const u8)) !void { const conf = self.conf; for (self.stos, 0..) |item, indx| { if (!try fail.failOkay(self.dbzz, item.name, nowz)) continue; var psyn = synz.*; psyn.store = if (kitz) |ktzz| mirr.fanzStor(try mkit.fanzForz(ktzz, aren, self.dbzz, self.iozz, nowz, self.conf, indx, false)) else item.store; psyn.vnam = item.name; psyn.copy = if (kitz != null) null else try copyFirs(self, nowz, indx); const pres = pclo.purgRunz(&psyn, aren, nowz, item.capb) catch |err3| { fres.errs += 1; if (!self.dryz) try fail.failBadz(self.dbzz, item.name, nowz, err3 == error.CloudDeny, conf.clou_fail_runs); continue; }; fres.pac4 += pres.pac4; fres.kept += pres.kept; fres.comp += pres.comp; fres.bads += pres.bads; if (pres.act2 == .young) { try alrtAddz(aren, alrt, "{s}: cloud pages at the high mark and every pack is younger than {d} days, nothing to purge; uploads move to the next vendor", .{ item.name, conf.purg_clou_mini_days }); if (!self.dryz) try fail.failFull(self.dbzz, item.name, nowz); } if (pres.act2 == .upgr) try alrtAddz(aren, alrt, "{s}: cloud pages at the high mark and clou_poli_mode is upgr: upgrade the plan or set purg", .{item.name}); if (pres.limd) try alrtAddz(aren, alrt, "{s}: purge limited to {d}% of the cap per run, still above the low mark; it continues next run", .{ item.name, conf.purg_maxx_pctz }); if (pres.bads > 0) try alrtAddz(aren, alrt, "{s}: {d} pack(s) could not be verified and were kept", .{ item.name, pres.bads }); }
if (!self.dryz) { _ = try sync.ledgBack(synz, aren); try sync.vendBack(synz, self.stos[0].name); } const sqdz = self.sqls[qidx]; if (pdbz.dbzzRunz(synz, aren, nowz, capzSqlz(self, kitz, qidx))) |dres| { fres.blan += dres.blan; fres.gone += dres.gone; if (dres.act2 == .alert) try alrtAddz(aren, alrt, "{s}: cloud database still above the high mark after purging; free space or upgrade the plan", .{sqdz.name}); if (dres.act2 == .upgr) try alrtAddz(aren, alrt, "{s}: cloud database at the high mark and clou_poli_mode is upgr", .{sqdz.name}); if (dres.limd) try alrtAddz(aren, alrt, "{s}: database purge limited per run; it continues next run", .{sqdz.name}); } else |err3| { fres.errs += 1; if (!self.dryz) try fail.failBadz(self.dbzz, sqdz.name, nowz, err3 == error.CloudDeny, conf.clou_fail_runs); }
var lcal: ploc.Loca = .{ .iozz = self.iozz, .dbzz = self.dbzz, .dirz = self.dirz, .conf = conf, .dryz = self.dryz, .capz = self.lcap }; fres.loca = try ploc.locaRunz(&lcal, aren, nowz); if (fres.loca.act2 == .stuck) try alrtAddz(aren, alrt, "local data folder at the high mark and no verified file can be pruned: fix the cloud sync", .{}); fres.live = try kplv.liveRunz(synz, aren, nowz); fres.veri = try kplv.veriRunz(synz, aren, nowz); if (fres.veri.lost > 0) try alrtAddz(aren, alrt, "verify: {d} entries lost (bad pack and no local copy)", .{fres.veri.lost}); }
pub fn flowSync(self: *Flow, aren: std.mem.Allocator, nowz: i64) !Fres { var fres: Fres = .{}; var alrt: std.ArrayList([]const u8) = .empty; var skps: std.ArrayList([]const u8) = .empty; var skpq: std.ArrayList([]const u8) = .empty; const kitz = try kitzMake(self, aren, nowz); var las2: anyerror = error.NotConfigured; var good: ?sync.Sync = null; var qgud: usize = 0; var tri2: u8 = 0; while (tri2 < 3) : (tri2 += 1) { fres.tris = tri2 + 1; const sidx = (try pickFirs(self, aren, nowz, true, skps.items)) orelse { las2 = error.CloudDeny; break; }; const qidx = (try pickFirs(self, aren, nowz, false, skpq.items)) orelse { las2 = error.CloudDeny; break; }; var synz = try makeSync(self, aren, nowz, sidx, qidx, kitz); var rslt: sync.Sres = .{}; sync.syncRunx(&synz, aren, nowz, &rslt) catch |err3| { las2 = err3; if (rslt.lays == 0) return err3; const blok = err3 == error.CloudDeny; if (rslt.lays & sync.LAYZ_STOR != 0) { try fail.failBadz(self.dbzz, self.stos[sidx].name, nowz, blok, self.conf.clou_fail_runs); try skps.append(aren, self.stos[sidx].name); if (kitz) |ktzz| mkit.vendFail(ktzz, true, sidx); } if (rslt.lays & sync.LAYZ_SQLZ != 0) { try fail.failBadz(self.dbzz, self.sqls[qidx].name, nowz, blok, self.conf.clou_fail_runs); try skpq.append(aren, self.sqls[qidx].name); if (kitz) |ktzz| mkit.vendFail(ktzz, false, qidx); } try outb.outbSoon(self.dbzz, nowz); continue; }; try fail.failGood(self.dbzz, self.stos[sidx].name); try fail.failGood(self.dbzz, self.sqls[qidx].name); fres.sres = rslt; fres.stor = self.stos[sidx].name; fres.sqlv = self.sqls[qidx].name; good = synz; qgud = qidx; break; } var syn3 = good orelse return las2; _ = snap.snapRunz(syn3.dbzz, syn3.store, syn3.iozz, aren) catch |err3| try alrtAddz(aren, &alrt, "car rows not copied to the cloud: {s}", .{@errorName(err3)}); if (self.ckey) |kez| _ = cbak.backClou(aren, syn3.iozz, syn3.dbzz, syn3.store, kez, nowz, self.conf.cont_week_keep) catch |err3| try alrtAddz(aren, &alrt, "contact backup not copied to the cloud: {s}", .{@errorName(err3)}); try phas(self, aren, nowz, &syn3, qgud, kitz, &fres, &alrt); if (kitz) |ktzz| fres.mirr = try mkit.kitzFini(ktzz, aren, self.dbzz, nowz, self.conf, &syn3, &alrt, self.dryz); fres.alrt = alrt.items; return fres; }
pub fn flowPurg(self: *Flow, aren: std.mem.Allocator, nowz: i64) !Fres { var fres: Fres = .{}; var alrt: std.ArrayList([]const u8) = .empty; const sidx = (try pickFirs(self, aren, nowz, true, &.{})) orelse return error.CloudDeny; const qidx = (try pickFirs(self, aren, nowz, false, &.{})) orelse return error.CloudDeny; const kitz = try kitzMake(self, aren, nowz); var synz = try makeSync(self, aren, nowz, sidx, qidx, kitz); fres.stor = self.stos[sidx].name; fres.sqlv = self.sqls[qidx].name; try phas(self, aren, nowz, &synz, qidx, kitz, &fres, &alrt); if (kitz) |ktzz| fres.mirr = try mkit.kitzFini(ktzz, aren, self.dbzz, nowz, self.conf, &synz, &alrt, self.dryz); fres.alrt = alrt.items; return fres; }
